import math

def viterbi(obs={{obs}}, states={{states}}, start_p={{start_p}}, trans_p={{trans_p}}, emit_p={{emit_p}}):
    V = [{}]; path = {}
    for s in states:
        V[0][s] = math.log(start_p[s] + 1e-12) + math.log(emit_p[s][obs[0]] + 1e-12)
        path[s] = [s]
    for t in range(1, len(obs)):
        V.append({}); new_path = {}
        for s in states:
            prob, prev = max((V[t-1][p0] + math.log(trans_p[p0][s] + 1e-12) + math.log(emit_p[s][obs[t]] + 1e-12), p0) for p0 in states)
            V[t][s] = prob; new_path[s] = path[prev] + [s]
        path = new_path
    prob, state = max((V[-1][s], s) for s in states)
    return prob, path[state]
